1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.CheckDigit;
8	import org.springframework.samples.petclinic.model.CustomerCode;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.model.OwnerIdentity;
