12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    Owner toOwner(OwnerDto ownerDto);
35	
36	    /** Format an owner's name as 'LastName, FirstName' for display. */
37	    default String displayName(Owner owner) {
38	        return owner.getLastName() + ", " + owner.getFirstName();
39	    }
40	
41	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
42	    default String initials(Owner owner) {
43	        return initial(owner.getFirstName()) + initial(owner.getLastName());
44	    }
45	
46	    private static String initial(String name) {
47	        return Character.toUpperCase(name.charAt(0)) + ".";
48	    }
49	
50	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
51	     * last two digits of the registrationDate year. */
52	    default String membershipNumber(Owner owner) {
53	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
54	            return null;
55	        }
56	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
57	    }
58	
59	    /** The owner's membership level from 1 to 3: starts at 1, plus 1 when an email is present,
60	     * plus 1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
61	    default int membershipLevel(Owner owner) {
62	        int level = 1;
63	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
64	        if (hasEmail) {
65	            level++;
66	        }
67	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
68	            level++;
69	        }
70	        return Math.min(level, 3);
71	    }
72	
73	    /** The owner's canonical region: the REGION segment of the customer code (see
74	     * {@link CustomerCode}), or null when the customer code is unset. */
75	    default String locality(Owner owner) {
76	        return CustomerCode.region(owner.getCustomerCode());
77	    }
78	
79	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
80	    default String contactPreference(Owner owner) {
81	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
82	        return hasEmail ? "EMAIL" : "PHONE";
83	    }
84	
85	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
86	    default String identityKey(Owner owner) {
87	        return OwnerIdentity.of(owner);
88	    }
89	
90	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
91	    default Integer checkDigit(Owner owner) {
92	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
93	    }
94	
95	    @Mapping(target = "id", ignore = true)
96	    @Mapping(target = "pets", ignore = true)
97	    @Mapping(target = "customerCode", ignore = true)
98	    @Mapping(target = "householdId", ignore = true)
99	    @Mapping(target = "namesakeCount", ignore = true)
100	    @Mapping(target = "householdSize", ignore = true)
101	    @Mapping(target = "bulkSignupWarning", ignore = true)
102	    Owner toOwner(OwnerFieldsDto ownerDto);
103	
104	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
105	
